usage:
This 'Echo Reversal Protocol' system allows Lyra to rewind a 'MemoryObject' in the game world at the cost of one of her 'MemoryFragment's. To use this recipe:

1.  **Create `mnemonic_retro_causality.gd`**: Save the provided GDScript code as `mnemonic_retro_causality.gd` and attach it to a global `Node` (e.g., a `GameManager` singleton or a child of Lyra's player node).

2.  **Create `temporal_distortion.gdshader`**: Save the following GLSL code as `temporal_distortion.gdshader`:

    glsl
// temporal_distortion.gdshader
shader_type spatial;
render_mode blend_mix, depth_draw_opaque, cull_back, diffuse_lambert, specular_schlick_ggx;

uniform sampler2D texture_albedo : hint_albedo;
uniform vec4 albedo : source_color = vec4(1.0);

uniform float distortion_strength : hint_range(0.0, 1.0) = 0.1;
uniform float distortion_speed : hint_range(0.0, 10.0) = 5.0;
uniform float chromatic_aberration_strength : hint_range(0.0, 0.1) = 0.005;
uniform float time_progress : hint_range(0.0, 1.0) = 0.0; // 0.0 at start of rewind, 1.0 at end

void fragment() {
	vec2 base_uv = UV;

	// Wave distortion on UVs
	float wave_offset_x = sin(base_uv.y * 20.0 + TIME * distortion_speed) * distortion_strength * (1.0 - time_progress);
	float wave_offset_y = cos(base_uv.x * 20.0 + TIME * distortion_speed * 0.7) * distortion_strength * (1.0 - time_progress);
	vec2 distorted_uv = base_uv + vec2(wave_offset_x, wave_offset_y);

	// Chromatic Aberration by sampling texture at slightly offset UVs
	vec3 color_r = texture(texture_albedo, distorted_uv + vec2(chromatic_aberration_strength, 0.0) * (1.0 - time_progress)).rgb;
	vec3 color_g = texture(texture_albedo, distorted_uv).rgb;
	vec3 color_b = texture(texture_albedo, distorted_uv - vec2(chromatic_aberration_strength, 0.0) * (1.0 - time_progress)).rgb;

	// Combine colors and apply a temporal tint
	vec3 final_color = vec3(color_r.r, color_g.g, color_b.b);
	vec3 temporal_tint = mix(vec3(0.0, 0.5, 1.0), vec3(1.0), time_progress); // Blueish at start, fades to white
	final_color = mix(final_color, temporal_tint, 0.3 * (1.0 - time_progress)); // Apply tint more strongly at start

	ALBEDO = final_color * albedo.rgb;
	ALPHA = albedo.a;
}


3.  **Create `ShaderMaterial` Resource**: In the Godot editor, create a new `ShaderMaterial` resource (e.g., `res://temporal_distortion_mat.tres`). Assign the `temporal_distortion.gdshader` to its `Shader` property. Then, assign this `ShaderMaterial` resource to the `Temporal Distortion Material` property of your `mnemonic_retro_causality.gd` node.

4.  **Create `memory_fragment.gd`**: Save the following GDScript code as `memory_fragment.gd`:

    gdscript
# memory_fragment.gd
extends Resource
class_name MemoryFragment

@export var fragment_name: String = "Untitled Fragment"
@export_multiline var description: String = "A piece of Lyra's past."
@export_multiline var effect_on_lyra: String = "No discernible effect yet." # e.g., "Reduced max stamina", "Lost knowledge of X"
@export var is_decayed: bool = false

func decay():
	if not is_decayed:
		is_decayed = true
		# In a real game, this would trigger actual stat changes or story flags
		print("Memory Fragment '%s' has decayed. Effect: %s" % [fragment_name, effect_on_lyra])


5.  **Create `MemoryFragment` Resources**: In the Godot editor, create new `MemoryFragment` resources (e.g., `res://memory_fragment_childhood_home.tres`, `res://memory_fragment_first_star_map.tres`). Configure their `Fragment Name`, `Description`, and `Effect On Lyra` properties. These are the memories Lyra can sacrifice.

6.  **Create `memory_object.gd`**: Save the following GDScript code as `memory_object.gd`:

    gdscript
# memory_object.gd
extends RigidBody3D
class_name MemoryObject

# This script enables a 3D object to be rewound to a previously saved state,
# applying a temporal distortion effect during the rewind.

@export var save_initial_state_on_ready: bool = true
@export var rewind_speed_multiplier: float = 1.0 # Adjust tween speed

var _initial_transform: Transform3D
var _initial_linear_velocity: Vector3
var _initial_angular_velocity: Vector3
var _initial_mode: RigidBody3D.RigidBodyMode

var _original_material: Material # Store the original material of the MeshInstance3D
var _rewind_tween: Tween
var _mesh_instance: MeshInstance3D

func _ready():
	_mesh_instance = get_node_or_null("MeshInstance3D") # Assumes a child MeshInstance3D
	if not _mesh_instance:
		push_error("MemoryObject requires a MeshInstance3D child named 'MeshInstance3D'.")
		set_process(false)
		return

	if save_initial_state_on_ready:
		save_current_state()

func save_current_state():
	_initial_transform = global_transform
	_initial_linear_velocity = linear_velocity
	_initial_angular_velocity = angular_velocity
	_initial_mode = mode
	if _mesh_instance and _mesh_instance.mesh and _mesh_instance.mesh.get_surface_override_material(0):
		_original_material = _mesh_instance.mesh.get_surface_override_material(0)
	elif _mesh_instance and _mesh_instance.get_active_material(0):
		_original_material = _mesh_instance.get_active_material(0)
	else:
		_original_material = null
	print("Initial state saved for %s." % name)

func start_rewind(duration: float, temporal_material: ShaderMaterial):
	if _rewind_tween and _rewind_tween.is_running():
		_rewind_tween.kill() # Stop any ongoing rewind

	# Apply temporal distortion material
	if _mesh_instance and temporal_material:
		var new_material = temporal_material.duplicate() # Duplicate to allow per-instance parameter changes
		if _original_material:
			# Try to copy albedo texture if original material has one
			if _original_material is StandardMaterial3D and new_material is ShaderMaterial:
				var albedo_tex = _original_material.albedo_texture
				if albedo_tex:
					new_material.set_shader_parameter("texture_albedo", albedo_tex)
		_mesh_instance.set_surface_override_material(0, new_material)
		new_material.set_shader_parameter("time_progress", 0.0) # Start at 0

	# Disable physics and clear velocities
	mode = RigidBody3D.MODE_STATIC
	linear_velocity = Vector3.ZERO
	angular_velocity = Vector3.ZERO

	_rewind_tween = create_tween()
	_rewind_tween.set_speed_scale(rewind_speed_multiplier)
	_rewind_tween.tween_property(self, "global_transform", _initial_transform, duration).set_trans(Tween.TRANS_LINEAR).set_ease(Tween.EASE_IN_OUT)

	# Animate shader parameter for visual feedback
	if _mesh_instance and temporal_material:
		_rewind_tween.tween_method(Callable(self, "_update_shader_time_progress"), 0.0, 1.0, duration).set_trans(Tween.TRANS_LINEAR)

	_rewind_tween.play()
	print("Rewind started for %s." % name)

func end_rewind(from_timer: bool = false):
	if _rewind_tween and _rewind_tween.is_running():
		_rewind_tween.kill()

	# Restore original material
	if _mesh_instance:
		_mesh_instance.set_surface_override_material(0, _original_material)

	# Restore physics state
	mode = _initial_mode
	linear_velocity = _initial_linear_velocity
	angular_velocity = _initial_angular_velocity

	print("Rewind ended for %s." % name)

func _update_shader_time_progress(progress: float):
	if _mesh_instance and _mesh_instance.get_surface_override_material(0) is ShaderMaterial:
		(_mesh_instance.get_surface_override_material(0) as ShaderMaterial).set_shader_parameter("time_progress", progress)


7.  **Create `MemoryObject` Scenes**: For any physical object Lyra can rewind (e.g., a broken bridge, a collapsed wall), create a `RigidBody3D` node. Add a `MeshInstance3D` child to it (named `MeshInstance3D`) and assign a mesh and material. Attach the `memory_object.gd` script to this `RigidBody3D` node. Ensure `Save Initial State On Ready` is checked if you want its initial state to be saved when the scene loads.

8.  **Triggering the Protocol**: When Lyra needs to rewind an object, call the `trigger_echo_reversal` method on your `mnemonic_retro_causality.gd` node, passing the `MemoryObject` instance as an argument:

    gdscript
    # Example from Lyra's script or an interaction script
    var game_manager = get_node("/root/GameManager") # Replace with your manager's path
    var target_object = $Path/To/MemoryObject # Replace with the actual MemoryObject node

    if game_manager and target_object:
        game_manager.trigger_echo_reversal(target_object)


    The system will automatically select and decay one of Lyra's active memory fragments, and the `MemoryObject` will visually and physically rewind to its initial state for the specified `rewind_duration`.
